/// <summary>
/// PricingAttribute of table <c>CustTable</c> field ShipCarrierAccount.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeCustTableShipCarrierAccount extends UPSPricingAttributeCustTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, ShipCarrierAccount);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::String);
    CustTable   custTable;

    while select ShipCarrierAccount from custTable
        group by ShipCarrierAccount
    {
        ret.add(custTable.ShipCarrierAccount);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustTable, ShipCarrierAccount));
    qbr.value(queryValue(_value));
}
